-- ============================================================
-- Baseline schema, matching the entities as they stood before
-- Flyway was introduced.
--
-- Against an already-populated database (production), Flyway's
-- baseline-on-migrate stamps this version as already applied
-- without running it - this file only actually executes against
-- a genuinely empty schema (a fresh local Postgres volume, or a
-- brand-new environment).
--
-- Do not edit this file once it has been applied anywhere -
-- Flyway checksums it and will refuse to start if it changes.
-- Schema changes from here on go in new V3__..., V4__... files.
-- ============================================================

CREATE TABLE tournaments (
    id                      BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    version                 BIGINT NOT NULL DEFAULT 0,
    name                    VARCHAR(200) NOT NULL,
    description             VARCHAR(1000),
    location                VARCHAR(200) NOT NULL,
    tournament_date         DATE NOT NULL,
    registration_deadline   DATE,
    registration_open       BOOLEAN NOT NULL,
    organizer               VARCHAR(100),
    contact_email           VARCHAR(100),
    rules                   VARCHAR(2000),
    started                 BOOLEAN NOT NULL,
    completed               BOOLEAN NOT NULL,
    created_at              TIMESTAMP NOT NULL,
    updated_at              TIMESTAMP NOT NULL
);

CREATE TABLE divisions (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    version             BIGINT NOT NULL DEFAULT 0,
    tournament_id       BIGINT NOT NULL REFERENCES tournaments (id),
    name                VARCHAR(200) NOT NULL,
    belt_rank           VARCHAR(30),
    age_category        VARCHAR(30) NOT NULL,
    gender              VARCHAR(20) NOT NULL,
    weight_class        VARCHAR(50),
    bracket_type        VARCHAR(30) NOT NULL,
    matches_generated   BOOLEAN NOT NULL,
    completed           BOOLEAN NOT NULL,
    created_at          TIMESTAMP NOT NULL,
    updated_at          TIMESTAMP NOT NULL
);
CREATE INDEX idx_division_tournament ON divisions (tournament_id);
CREATE INDEX idx_division_age ON divisions (age_category);

CREATE TABLE athletes (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    version             BIGINT NOT NULL DEFAULT 0,
    name                VARCHAR(100) NOT NULL,
    date_of_birth       DATE,
    age                 INTEGER NOT NULL,
    gender              VARCHAR(20) NOT NULL,
    belt_rank           VARCHAR(30) NOT NULL,
    weight              DOUBLE PRECISION NOT NULL,
    team                VARCHAR(100),
    coach_name          VARCHAR(100),
    email               VARCHAR(100),
    phone               VARCHAR(20),
    experience_notes    VARCHAR(500),
    created_at          TIMESTAMP NOT NULL,
    updated_at          TIMESTAMP NOT NULL
);
CREATE INDEX idx_athlete_belt ON athletes (belt_rank);
CREATE INDEX idx_athlete_gender ON athletes (gender);
CREATE INDEX idx_athlete_age ON athletes (age);

CREATE TABLE matches (
    id                          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    version                     BIGINT NOT NULL DEFAULT 0,
    division_id                 BIGINT NOT NULL REFERENCES divisions (id),
    athlete1_id                 BIGINT REFERENCES athletes (id),
    athlete2_id                 BIGINT REFERENCES athletes (id),
    winner_id                   BIGINT REFERENCES athletes (id),
    status                      VARCHAR(20) NOT NULL,
    round_number                INTEGER NOT NULL,
    match_position               INTEGER,
    mat_number                  INTEGER,
    scheduled_time               TIMESTAMP,
    athlete1_points              INTEGER NOT NULL,
    athlete2_points              INTEGER NOT NULL,
    athlete1_advantages          INTEGER NOT NULL,
    athlete2_advantages          INTEGER NOT NULL,
    athlete1_penalties           INTEGER NOT NULL,
    athlete2_penalties           INTEGER NOT NULL,
    finished_by_submission        BOOLEAN NOT NULL,
    submission_type              VARCHAR(100),
    duration_seconds             INTEGER,
    notes                       VARCHAR(1000),
    created_at                  TIMESTAMP NOT NULL,
    updated_at                  TIMESTAMP NOT NULL
);
-- Only the 3 indexes that originally existed - the 3 missing FK
-- indexes (athlete1_id, athlete2_id, winner_id) are added by V2,
-- matching the real history of this fix.
CREATE INDEX idx_match_division ON matches (division_id);
CREATE INDEX idx_match_status ON matches (status);
CREATE INDEX idx_match_round ON matches (round_number);

CREATE TABLE users (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    username            VARCHAR(50) NOT NULL,
    email               VARCHAR(100) NOT NULL,
    password            VARCHAR(255) NOT NULL,
    full_name           VARCHAR(100) NOT NULL,
    role                VARCHAR(20) NOT NULL,
    enabled             BOOLEAN NOT NULL,
    account_non_locked  BOOLEAN NOT NULL,
    created_at          TIMESTAMP NOT NULL,
    updated_at          TIMESTAMP NOT NULL,
    CONSTRAINT uk_users_username UNIQUE (username),
    CONSTRAINT uk_users_email UNIQUE (email)
);
-- These duplicate the uniqueness already enforced by the two
-- constraints above - that duplication is intentional here, since
-- it faithfully reproduces the "Duplicate Index" state the Supabase
-- advisor flagged. V2 drops these two, leaving just the constraints.
CREATE UNIQUE INDEX idx_user_username ON users (username);
CREATE UNIQUE INDEX idx_user_email ON users (email);

-- division_athletes: @ManyToMany join table for Division.athletes.
-- Unique constraint only (no primary key) - that's the "No Primary
-- Key" state the advisor flagged. V2 promotes it to a real PK.
CREATE TABLE division_athletes (
    division_id   BIGINT NOT NULL REFERENCES divisions (id),
    athlete_id    BIGINT NOT NULL REFERENCES athletes (id),
    CONSTRAINT uk_division_athlete UNIQUE (division_id, athlete_id)
);
